import { Component, ElementRef, HostBinding, Input, OnInit, ViewChild } from '@angular/core';
import { ActivatedRoute, NavigationExtras, Router } from '@angular/router';

import { NavController, Platform } from '@ionic/angular';
import { routeAnimation } from '../../shared';
import { HttpClientService } from '../../shared/http-client.service';
import { isNotNullOrUndefined } from 'codelyzer/util/isNotNullOrUndefined';
import { environment } from '../../../environments/environment';
import { Key } from 'protractor';
import { debug } from 'console';
import { ModalService } from 'ng-zorro-antd-mobile';

// 扫描码
import { Plugins } from '@capacitor/core';
import 'scanner';
import { areAllEquivalent } from '@angular/compiler/src/output/output_ast';
const { Scanner } = Plugins;

@Component({
    selector: 'app-modify-pwd',
    templateUrl: './modify-pwd.page.html',
    styleUrls: ['./modify-pwd.page.scss'],
    animations: [    // 路由动画
        routeAnimation
    ]
})
export class ModifyPwdPage implements OnInit {

    pwdObj = {
        newPwd: undefined,
        againPwd: undefined
    }

    loginUserId; // 登录用户名
    showLoading = false;
    validResult;

    strongPwdPolicy = false;
    isStrongPwd = false; // 判断参数是否为强密码
    strongPwdRegExp;
    ruleList = [];

    pwdForced;

    isSuccess = false;
    encodeKey;
    key;
    @HostBinding('@routeAnimation') state;   // 路由动画

    constructor(
        private router: Router,
        public navCtrl: NavController,
        private http: HttpClientService,
        private route: ActivatedRoute,
        private eleRef: ElementRef,
        private alertModal: ModalService,
        private platform: Platform
    ) {
        
    }
    
    ngOnInit(): void {
        
    }

    ionViewWillEnter() {
        this.init();
    }

    init() {
    
    this.pwdForced = sessionStorage.getItem('pwdForced') === 'true';
    
        if (isNotNullOrUndefined(sessionStorage.getItem('loginUserId'))){
            this.loginUserId = sessionStorage.getItem('loginUserId');
        }

        if (isNotNullOrUndefined(sessionStorage.getItem('rcp_open_pw_level_verification_switch'))){
            this.strongPwdPolicy = sessionStorage.getItem('rcp_open_pw_level_verification_switch') === 'true';

            if (isNotNullOrUndefined(sessionStorage.getItem('isStrongPwd'))){
                this.isStrongPwd = sessionStorage.getItem('isStrongPwd') === '1';
            }

            if (isNotNullOrUndefined(sessionStorage.getItem('rcp_open_pwd_rule'))){
                this.ruleList = sessionStorage.getItem('rcp_open_pwd_rule').split('||');
            }

            if (isNotNullOrUndefined(sessionStorage.getItem('rcp_open_pwd_reg'))){
                this.strongPwdRegExp = sessionStorage.getItem('rcp_open_pwd_reg');
            }

        }
    }

    navTo(dest){
        this.router.navigate([dest]);
    }

    // 路由返回
    routeBack() {
        //this.router.navigate(['/SelectCensusAddressTree']);
        this.router.navigate(['/tabs/tab1']);
    }

    // logout
    showLogoutAlert() {
        this.alertModal.alert('', '确认退出?', [
            { text: '取消', onPress: () => { } },
            {
                text: '退出', onPress: () => {
                    var ip = sessionStorage.getItem('ip');
                    sessionStorage.clear();
                    sessionStorage.setItem('ip', ip);
                    this.router.navigate(['/login']);
                }
            }
        ]);
    }
    logout() {
        this.showCustom(false);
        this.showLogoutAlert();
    }

    // 弹框
    showCustom(value) {
        if (value) {
            setTimeout(() => {
                this.eleRef.nativeElement.querySelector('.tab-load-model-input').focus();
            }, 10);
            const keyboard = Plugins.Keyboard;
            keyboard.show();
        } else {
        }
    }

    getKey() {
        this.http
            .getNotHeard(`rcp/open/api/key`)
            .subscribe( data => {
                if (data['code'] === '0'){
                    this.encodeKey = data['data']['encode_key'];
                    this.key = data['data']['key'];
                    this.modifyPwd();
                }
            });
    }
    modifyPwd(){
        let flag;
        if(!this.pwdObj.newPwd || !this.pwdObj.againPwd){
            this.validResult = '密码不能为空'
            return false;
        }
        if(/\s/.test(this.pwdObj.newPwd) || /\s/.test(this.pwdObj.newPwd)){
            this.validResult = '密码不能包含空格'
            return false;
        }

        if(this.pwdObj.newPwd != this.pwdObj.againPwd){
            this.validResult = '新密码与确认密码不同，请重新输入'
            return false;
        }

        if(this.strongPwdPolicy){
            if(!new RegExp(this.strongPwdRegExp).test(this.pwdObj.newPwd)){
                this.validResult = '新密码不符合强密码规则，请重新输入'
                return false;
            }
        }

        this.validResult = '';
        const newPwd = window['encryptByDES'](this.pwdObj.newPwd, this.encodeKey );
        const cond = {
            password: newPwd,
            //userId: this.loginUserId,
            key: this.key
        }

        this.http.post('rcp/api/user/modifyPassword', cond, '修改密码','修改密码')
                .subscribe( data => {
            if (data['isSuccess']){
                this.validResult = '密码修改成功，请重新登录';
                this.isSuccess = true;
                this.pwdObj.newPwd = undefined;
                this.pwdObj.againPwd = undefined;
                setTimeout( () => {
                    let ip = sessionStorage.getItem('ip');
                    sessionStorage.clear();
                    sessionStorage.setItem('ip', ip);
                    this.isSuccess = false;
                    this.validResult = '';
                    this.router.navigate(['/']);
                }, 2000);
            }else{
                this.validResult = '密码修改失败，请稍后再试';
            }
        });
       
    }
    
}
